262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Override
265	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
266	        Owner owner = this.clinicService.findOwnerById(ownerId);
267	        if (owner != null) {
268	            Pet pet = owner.getPet(petId);
269	            if (pet != null) {
270	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
271	            }
272	        }
273	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	    }
275	
276	    /**
277	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
278	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
279	     * the request body already rejects null and empty values, but permits whitespace-only strings
280	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
281	     * that gap so every required field must carry a non-blank value.
282	     *
283	     * @param ownerFieldsDto the submitted owner fields
284	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
285	     */
286	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
287	        List<String> missing = new ArrayList<>();
288	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
289	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
290	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
291	            missing.add("address");
292	        }
293	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
294	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
295	        if (!missing.isEmpty()) {
296	            throw new InvalidOwnerFieldsException(missing);
297	        }
298	    }
299	
300	    /**
301	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
302	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
303	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
304	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
305	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
306	     * {@link PostcodeValidator}.
307	     *
308	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
309	     *                       {@link #rejectBlankOwnerFields} having already run)
310	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
311	     */
312	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
313	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
314	            throw new InvalidOwnerFieldsException(List.of("postcode"));
315	        }
316	    }
317	
318	    private void addIfBlank(List<String> missing, String fieldName, String value) {
319	        if (isBlank(value)) {
320	            missing.add(fieldName);
321	        }
322	    }
323	
324	    private boolean isBlank(String value) {
325	        return value == null || value.isBlank();
326	    }
327	
328	    /**
329	     * Normalizes the submitted address on create to its canonical form (see
330	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
331	     * stored and returned, and the form every later address comparison (the required-field check,
332	     * household duplicate detection and the shared household id) is judged on. The structured fields
333	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
334	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
335	     * derived from them when a structured {@code addressLine1} is present, falling back to the
336	     * normalized flat {@code address} otherwise. Any absent field is left absent so
337	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
338	     * after normalization likewise reduces to the empty string and is rejected there.
339	     *
340	     * @param ownerFieldsDto the submitted owner fields
341	     */
342	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
343	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
344	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
345	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
346	        ownerFieldsDto.setAddressLine1(addressLine1);
347	        ownerFieldsDto.setAddressLine2(addressLine2);
348	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
349	    }
350	
351	    /**
352	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
353	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
354	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
355	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
356	     * is the single value every later reader of the address (the required-field check, household
357	     * duplicate detection and the shared household id) is judged on.
358	     *
359	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
360	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
361	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
362	     * @return the composed flat address, or {@code null} when no address form was supplied
363	     */
364	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
365	        if (isBlank(addressLine1)) {
366	            return flatAddress;
367	        }
368	        if (isBlank(addressLine2)) {
369	            return addressLine1;
370	        }
371	        return addressLine1 + " " + addressLine2;
372	    }
373	
374	    /**
375	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
376	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
377	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
378	     * {@code 400 Bad Request}.
379	     *
380	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
381	     *                       {@link #rejectBlankOwnerFields} having already run)
382	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
383	     */
384	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
385	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
386	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
387	        ownerFieldsDto.setTelephone(normalized);
388	    }
389	
390	    /**
391	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
392	     * untouched (email is optional). When present it is reduced to its canonical form (see
393	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
394	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
395	     *
396	     * @param ownerFieldsDto the submitted owner fields
397	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
398	     *                                     or its domain is on the disposable-domain blocklist
399	     */
400	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
401	        String email = ownerFieldsDto.getEmail();
402	        if (email == null || email.isBlank()) {
403	            return;
404	        }
405	        String normalized = EmailNormalizer.normalize(email)
406	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
407	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
408	            throw new InvalidOwnerFieldsException(List.of("email"));
409	        }
410	        ownerFieldsDto.setEmail(normalized);
411	    }
412	
413	    /**
414	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
415	     * duplicate detection is now expressed through the single derived {@code identityKey}
416	     * ({@code normalizedTelephone + '|' + email + '|' + householdId}, see {@link OwnerIdentity}),
417	     * which replaces the previously separate telephone, email and household checks. Two owners denote
418	     * the same person when their identities collide on the telephone - the identity's distinguishing
419	     * component - so a create is rejected as a {@code 409 Conflict} when another owner already carries
420	     * the same normalized telephone. Because the telephone is part of the identity, two members of the
421	     * same household with different telephones have different identities and are both allowed; an email
422	     * or a household on its own no longer makes a duplicate.
423	     *
424	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
425	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
426	     * @param householdId    the household id derived for the owner being created (see
427	     *                       {@link HouseholdNormalizer#toHouseholdId})
428	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
429	     */
430	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String householdId) {
431	        String identityKey = OwnerIdentity.identityKey(
432	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
433	        String telephoneKey = TelephoneNormalizer.toComparisonKey(ownerFieldsDto.getTelephone());
434	        boolean inUse = this.clinicService.findAllOwners().stream()
435	            .filter(existing -> !existing.isDeleted())
436	            .map(Owner::getTelephone)
437	            .filter(Objects::nonNull)
438	            .map(TelephoneNormalizer::toComparisonKey)
439	            .anyMatch(telephoneKey::equals);
440	        if (inUse) {
441	            throw new DuplicateOwnerIdentityException(identityKey);
442	        }
443	    }
444	
445	    /**
446	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
447	     * both match the submitted values, compared case-insensitively. The count reflects only owners
448	     * already persisted at the time of the create, so the owner being created is never included.
449	     *
450	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
451	     *                  having already run)
452	     * @param lastName  the submitted last name (non-blank here)
453	     * @return the number of existing owners sharing the same first and last name
454	     */
455	    private int countNamesakes(String firstName, String lastName) {
456	        return (int) this.clinicService.findAllOwners().stream()
457	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
458	                && lastName.equalsIgnoreCase(owner.getLastName()))
459	            .count();
460	    }
461	
462	    /**
463	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
464	     * whose stored {@code householdId} equals the value derived for the owner being created. The
465	     * count reflects only owners already persisted at the time of the create, so the owner being
466	     * created is never included; callers add one to obtain the household size after this create.
467	     *
468	     * @param householdId the household identifier derived for the owner being created (see
469	     *                    {@link HouseholdNormalizer#toHouseholdId})
470	     * @return the number of existing owners already sharing that household
471	     */
472	    private int countHouseholdMembers(String householdId) {
473	        if (householdId == null) {
474	            return 0;
475	        }
476	        return (int) this.clinicService.findAllOwners().stream()
477	            .map(Owner::getHouseholdId)
478	            .filter(householdId::equals)
479	            .count();
480	    }
481	
482	    /**
483	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
484	     * owner with an address taken from the request, so routing that through this single method keeps the
485	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
486	     * household id.
487	     *
488	     * @param ownerFieldsDto the submitted owner fields
489	     * @return the address to store on the owner
490	     */
491	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
492	        return ownerFieldsDto.getAddress();
493	    }
494	
495	    /**
496	     * Derives the household id an owner should carry from its submitted fields (see
497	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
498	     * household id, so routing them through this single method keeps them agreed on which of the
499	     * owner's fields key the household.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
502	     *                       {@link #rejectBlankOwnerFields} having already run on create)
503	     * @return the owner's household id
504	     */
505	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
506	        return HouseholdNormalizer.toHouseholdId(
507	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
508	    }
509	
510	    /**
511	     * Rejects creating an owner that would join an existing household without declaring itself a
512	     * member. The household is keyed on (last name, postcode) through the derived {@code householdId}
513	     * (see {@link HouseholdNormalizer#toHouseholdId}), so a second owner sharing an existing owner's
514	     * last name and postcode denotes the same household. Such a create is reported as a {@code 409
515	     * Conflict} unless it opts in with {@code sharesHousehold}, in which case it is accepted as a
516	     * declared household member. Only owners already persisted (before this create) are considered.
517	     *
518	     * @param householdId     the household id derived for the owner being created
519	     * @param sharesHousehold whether the request opted in to sharing a household
520	     * @throws DuplicateOwnerHouseholdException if the household already exists and the request did not
521	     *                                          opt in with {@code sharesHousehold}
522	     */
523	    private void rejectHouseholdDuplicate(String householdId, boolean sharesHousehold) {
524	        if (sharesHousehold || householdId == null) {
525	            return;
526	        }
527	        boolean householdExists = this.clinicService.findAllOwners().stream()
528	            .filter(existing -> !existing.isDeleted())
529	            .map(Owner::getHouseholdId)
530	            .anyMatch(householdId::equals);
531	        if (householdExists) {
532	            throw new DuplicateOwnerHouseholdException(householdId);
533	        }
534	    }
535	
536	    /**
537	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
538	     * is none. The create has already cleared the hard-duplicate identity check
539	     * ({@link #rejectDuplicateIdentity}), so it is not an exact match of any existing owner; it is a
540	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code lastName}
541	     * (compared case-insensitively) and {@code postcode} while carrying a different normalized
542	     * telephone. The oldest such owner (the earliest persisted) is returned so the flag points at the
543	     * original record; owners with no postcode never match, since a shared postcode is required.
544	     *
545	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
546	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
547	     *         duplicate
548	     */
549	    private Integer findPossibleDuplicate(Owner owner) {
550	        String postcode = owner.getPostcode();
551	        if (postcode == null) {
552	            return null;
553	        }
554	        String telephoneKey = TelephoneNormalizer.toComparisonKey(owner.getTelephone());
555	        return this.clinicService.findAllOwners().stream()
556	            .filter(existing -> !existing.isDeleted())
557	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
558	            .filter(existing -> postcode.equals(existing.getPostcode()))
559	            .filter(existing -> existing.getTelephone() != null
560	                && !telephoneKey.equals(TelephoneNormalizer.toComparisonKey(existing.getTelephone())))
561	            .map(Owner::getId)
562	            .filter(Objects::nonNull)
563	            .min(Integer::compareTo)
564	            .orElse(null);
565	    }
566	
567	    /**
568	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
569	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
570	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
571	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
572	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
573	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
574	     * duplicate, so it is never flagged.
575	     *
576	     * @param owner           the owner being created, with telephone already normalized and
577	     *                        lastName/postcode set
578	     * @param sharesHousehold whether the request opted in to sharing a household
579	     */
580	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
581	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
582	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
583	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
584	    }
585	
586	    /**
587	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
588	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
589	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
590	     *
591	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
592	     *             run)
593	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
594	     */
595	    private void rejectCityAtCapacity(String city) {
596	        long ownersInCity = this.clinicService.findAllOwners().stream()
597	            .map(Owner::getCity)
598	            .filter(Objects::nonNull)
599	            .filter(city::equalsIgnoreCase)
600	            .count();
601	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
602	            throw new OwnerCityAtCapacityException(city);
603	        }
604	    }
605	
606	    /**
607	     * Resolves the effective registration date for a create, rolled onto a business day. The
608	     * supplied date is used when present, otherwise the server's current date; either way the result
609	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
610	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
611	     * stored {@code registrationDate}, the membership number's year segment and the daily
612	     * create-limit's per-day count - is judged on this adjusted date.
613	     *
614	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
615	     *                                 default to the server's current date
616	     * @return the effective registration date, guaranteed to fall on a business day
617	     */
618	    /**
619	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
620	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
621	     * adjustment; a future date cannot describe a registration that has already happened, so it is
622	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
623	     * server's current date) and any date on or before today are accepted.
624	     *
625	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
626	     *                                 omitted
627	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
628	     */
629	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
630	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
631	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
632	        }
633	    }
634	
635	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
636	        LocalDate registrationDate =
637	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
638	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
639	    }
640	
641	    /**
642	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
643	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
644	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
645	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
646	     * Too Many Requests}.
647	     *
648	     * @param registrationDate   the create's effective registration date, already rolled onto a
649	     *                           business day by {@link #effectiveRegistrationDate}
650	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
651	     *                           {@code registrationDate} equals {@code registrationDate}
652	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
653	     *                                              owner registrations
654	     */
655	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
656	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
657	            throw new OwnerDailyRegistrationLimitException(registrationDate);
658	        }
659	    }
660	
661	    /**
662	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
663	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
664	     * bulk-signup warning are judged on.
665	     *
666	     * @param registrationDate the create's effective registration date, already rolled onto a business
667	     *                         day by {@link #effectiveRegistrationDate}
668	     * @return the number of existing owners registered on that day
669	     */
670	    private long countRegisteredOn(LocalDate registrationDate) {
671	        return this.clinicService.findAllOwners().stream()
672	            .map(Owner::getRegistrationDate)
673	            .filter(registrationDate::equals)
674	            .count();
675	    }
676	}
