1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
23	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
24	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
25	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
27	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.util.FiscalYear.label(owner.getRegistrationDate()))")
28	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", org.springframework.samples.petclinic.util.FiscalYear.yearOf(owner.getRegistrationDate()) % 100))")
29	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
32	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
33	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
39	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
40	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
41	     */
42	    default String timezone(Owner owner) {
43	        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
44	        if (region == null) {
45	            return null;
46	        }
47	        return switch (region) {
48	            case "NSW" -> "Australia/Sydney";
49	            case "VIC" -> "Australia/Melbourne";
50	            case "QLD" -> "Australia/Brisbane";
51	            default -> null;
52	        };
53	    }
54	
55	    /**
56	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
57	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
58	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
59	     */
60	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
61	        java.time.LocalDate birthDate = owner.getBirthDate();
62	        java.time.LocalDate asOf = owner.getRegistrationDate();
63	        if (birthDate == null || asOf == null) {
64	            return null;
65	        }
66	        int years = java.time.Period.between(birthDate, asOf).getYears();
67	        if (years < 18) {
68	            return OwnerDto.AgeBandEnum.MINOR;
69	        }
70	        if (years < 65) {
71	            return OwnerDto.AgeBandEnum.ADULT;
72	        }
73	        return OwnerDto.AgeBandEnum.SENIOR;
74	    }
75	
76	    /**
77	     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
78	     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
79	     * when at least one fiscal year has elapsed since {@code registrationDate} (measured from
80	     * {@code registrationDate} to today, counting 1-July boundaries crossed).
81	     */
82	    default int membershipPoints(Owner owner) {
83	        int points = 0;
84	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
85	            points += 2;
86	        }
87	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
88	            points += 1;
89	        }
90	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
91	            points += 2;
92	        }
93	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
94	        if (registrationDate != null
95	                && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
96	                        registrationDate, java.time.LocalDate.now()) >= 1) {
97	            points += 3;
98	        }
99	        return points;
100	    }
101	
102	    /**
103	     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
104	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
105	     */
